customCSS:
.cCenterPanel {
padding: none !important;
margin: 0px;

}
.siteforceStarterBody .cCenterPanel {
    padding: none !important;

}
.siteforceStarterBody {
background: white !important;
    padding: none !important;

}

.siteforceContentArea{
   padding: none !important;

}

.comm-content-header{
 padding: 0px !important;   
}

.comm-content-footer{
 padding: 0px !important;   
}

/* Forçar cor do botão Next */
.slds-button_brand,
button.slds-button.brand,
button.slds-button.slds-button_brand {
    background-color: #0070d2 !important; /* Azul padrão Salesforce */
    color: #ffffff !important;            /* Texto branco */
    border: none !important;
}

/* Opcional: hover */
.slds-button_brand:hover,
button.slds-button.brand:hover,
button.slds-button.slds-button_brand:hover {
    background-color: #005fb2 !important; /* Azul mais escuro no hover */
    color: #ffffff !important;
}

.runtime_appointmentbookingResourceSlot:first-of-type {
    font-size: 0 !important;  /* oculta só o primeiro texto */
    border-bottom: none !important;
}

/* Aplica Salesforce Sans em toda a página */
html, body, * {
    font-family: "Arial", sans-serif !important;
}

.slds-text-heading_large[aria-label="Select Service Appointment Time"] {
    font-size: 0 !important; /* some com o texto original */
}

.slds-text-heading_large[aria-label="Select Service Appointment Time"]::after {
    content: "Select a Time with a Mosaic Representative";
    font-size: 1.5rem;   /* volta ao tamanho original */
    color: #000;         /* cor do texto */
}

.slds-radio input[type="radio"]:checked + .slds-radio_faux,
.slds-radio input[type="radio"]:checked + .slds-radio_faux span {
    background-color: #ffffff !important;
    color: #000000 !important;
}


/* Esconde o texto original */
h2.slds-text-heading_large.slds-text-align_center.slds-p-around_x-large {
    font-size: 0 !important;   /* deixa o texto invisível */
    border: none !important;   /* se tiver borda */
}

/* Insere o novo texto */
h2.slds-text-heading_large.slds-text-align_center.slds-p-around_x-large::after {
    content: "Thanks for scheduling time with a Mosaic representative. Be on the lookout for the meeting invite in your email inbox";
    font-size: 1.25rem; /* ajusta o tamanho */
    color: #000;        /* cor da fonte */
}
